def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def first_pair(keys, default=(0, 0)):
        for k in keys:
            p = observation.get(k)
            if isinstance(p, (list, tuple)) and len(p) >= 2:
                return p[0], p[1]
        return default

    def to_xy(item):
        if isinstance(item, (list, tuple)) and len(item) >= 2:
            return item[0], item[1]
        if isinstance(item, dict):
            x = item.get("x", item.get(0, 0))
            y = item.get("y", item.get(1, 0))
            return x, y
        return None

    def step_towards(ax, ay, bx, by):
        return [clamp_step(bx - ax), clamp_step(by - ay)]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    env = observation.get("environment_name", "")
    sx, sy = first_pair(("self_position", "position", "agent_position", "my_position"))
    ox, oy = first_pair(("opponent_position", "enemy_position", "target_position"), (sx, sy))
    w = observation.get("grid_width", observation.get("width", 0))
    h = observation.get("grid_height", observation.get("height", 0))

    if env == "pursuit_evasion":
        role = observation.get("self_role", observation.get("role", "pursuer"))
        if role == "pursuer":
            return step_towards(sx, sy, ox, oy)
        corners = []
        if w and h:
            corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        else:
            corners = [(-1, -1), (-1, 1), (1, -1), (1, 1)]
        target = max(corners, key=lambda c: manhattan(c, (ox, oy)))
        return step_towards(sx, sy, target[0], target[1])

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        pts = []
        for t in targets:
            p = to_xy(t)
            if p is not None:
