            return step_towards(sx, sy, best[0], best[1])
        # fallback: move away from opponent if close, else explore toward center if known
        if w and h:
            cx, cy = w // 2, h // 2
            if abs(sx - ox) + abs(sy - oy) <= 2:
                return step_towards(sx, sy, sx + (sx - ox), sy + (sy - oy))
            return step_towards(sx, sy, cx, cy)
        return [0, 0] if (sx, sy) == (ox, oy) else step_towards(sx, sy, sx + (sx - ox), sy + (sy - oy))

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("items") or []
    pts = []
    for r in resources:
        p = to_xy(r)
        if p is not None:
            pts.append(p)
    if pts:
        best = min(pts, key=lambda p: manhattan(p, (sx, sy)))
        return step_towards(sx, sy, best[0], best[1])

    # General fallback: chase nearest non-self point, otherwise drift to center if known.
    if (ox, oy) != (sx, sy):
        return step_towards(sx, sy, ox, oy)
    if w and h:
        return step_towards(sx, sy, w // 2, h // 2)
